class Solution:
    def sortArray(self, nums: List[int]) -> int:
        n = len(nums)
        def calc(t):
            arr = list(nums)
            pos = {v: i for i, v in enumerate(arr)}
            ht = (n - t) % n
            res, nxt = 0, 0
            while True:
                if pos[0] != ht:
                    need = (pos[0] + t) % n
                    src = pos[need]
                else:
                    while nxt < n and arr[nxt] == (nxt + t) % n:
                        nxt += 1
                    if nxt == n:
                        return res
                    src = nxt
                v = arr[src]
                arr[pos[0]], arr[src] = v, 0
                pos[v], pos[0] = pos[0], src
                res += 1
        return min(calc(0), calc(1))

