public:
    int sortArray(vector<int>& nums) {
        int n = nums.size();
        auto calc = [&](int t) {
            vector<int> arr = nums, pos(n);
            for (int i = 0; i < n; i++) pos[arr[i]] = i;
            int ht = (n - t) % n, res = 0, nxt = 0;
            while (true) {
                int src;
                if (pos[0] != ht) {
                    src = pos[(pos[0] + t) % n];
                } else {
                    while (nxt < n && arr[nxt] == (nxt + t) % n) nxt++;
                    if (nxt == n) return res;
                    src = nxt;
                }
                int v = arr[src];
                swap(arr[pos[0]], arr[src]);
                pos[v] = pos[0];
                pos[0] = src;
                res++;
            }
        };
        return min(calc(0), calc(1));
    }
};

