class Solution:
    def sortArray(self, nums: List[int]) -> int:
        n = len(nums)
        def calc(t):
            pos = [0] * n
            for i, v in enumerate(nums):
                pos[v] = i
            ht = (n - t) % n
            vis = [False] * n
            res = 0
            for s in range(n):
                if vis[s]:
                    continue
                L, j, hit = 0, s, False
                while not vis[j]:
                    vis[j] = True
                    L += 1
                    if j == ht:
                        hit = True
                    j = pos[(j + t) % n]
                if L > 1:
                    res += L + 1 - (2 if hit else 0)
            return res
        return min(calc(0), calc(1))

